    "title": "立冬遇强雨雪，湿冷攻击上线，今年台风生成个数刷新本世纪以来纪录",
    "link": "https://www.chinanews.com.cn/sh/2026/11-07/10728078.shtml",
    "pub_date": "2026-11-07 19:38:03",
    "author": "",
    "description": "立冬开场，下半年来强度最强、影响最南的冷空气强势上线，北方雨雪天气明显增多，且雨雪交杂。与此同时，南方大范围阴雨还在继续。今早，中央气象台暴雪预警和暴雨预警同时发布，这说明了此轮大范围强雨雪天气的强盛和少见；另外，这次河北和天津，同一个省市，同时出现在暴雪和暴雨预警里，很少见，也说明冷暖空气都很强。其中强降雪核心区域在河北东北部，由于强劲的南风遇上燕山山脉地形加持，个别点不排除特大暴雪的可能性。",
