    "content": "新华社北京11月7日电（记者曹嘉玥、吴文诩）第七届世界媒体峰会图片展7日在北京人民大会堂举办。图片展分为“凝聚广泛共识 共促多元交流”和“发展的中国 共同的机遇”两大主题，生动回顾中国媒体促进中外交流合作的精彩瞬间，多角度呈现中国推动高质量发展的生动故事，展现中国人民同世界人民和衷共济、携手共进的时代华章。 “凝聚广泛共识 共促多元交流”主题展览下设“共识之路”“交流之桥”两个篇章，共展出24张图片或照片。“共识之路”篇章回望世界媒体峰会从无到有、由点及面的发展轨迹，重点回顾了历届峰会的重要时刻，展现了全球媒体同行…"
