    "description": "新华社乌鲁木齐11月7日电 题：一颗“冰糖心” 甜了戈壁百姓好日子 新华社记者孙少雄、曹志恒、黄昱璋 秋风掠过新疆阿克苏红旗坡，连片苹果林铺展着深浅交错的绿。枝头果实染上红晕，清甜果香在林间弥漫开来。几十年前，这里还是黄沙肆虐、草木难生的戈壁荒滩。 一代代人接续治沙植绿，筑起了防风固沙的绿色屏障。如今，阿克苏地区苹果种植面积达55万亩，年产量98万吨，形成种植、仓储、加工、销售全链条，冰糖心苹果成为带动当地果农增收致富的“金果子”。 阿…",
    "content": "新华社乌鲁木齐11月7日电 题：一颗“冰糖心” 甜了戈壁百姓好日子 新华社记者孙少雄、曹志恒、黄昱璋 秋风掠过新疆阿克苏红旗坡，连片苹果林铺展着深浅交错的绿。枝头果实染上红晕，清甜果香在林间弥漫开来。几十年前，这里还是黄沙肆虐、草木难生的戈壁荒滩。 一代代人接续治沙植绿，筑起了防风固沙的绿色屏障。如今，阿克苏地区苹果种植面积达55万亩，年产量98万吨，形成种植、仓储、加工、销售全链条，冰糖心苹果成为带动当地果农增收致富的“金果子”。 阿克苏丰庆园农民专业合作社，位于阿克苏冰糖心苹果核心产区，坚持治沙与种果同步推进。…"
