    "description": "中新社上海11月7日电 (记者 尹倩芸)第140届广交会11月4日在广州闭幕，35.2万名境外采购商到会，现场达成意向出口成交额267.5亿美元。一天后，第九届中国国际进口博览会在上海开幕，全球企业携商品和技术而来，寻找中国市场机遇。",
