    "pub_date": "2026-11-07 19:23:52",
    "author": "",
    "description": "中新社上海11月7日电 (记者 尹倩芸 曾玥)正在上海举行的第九届中国国际进口博览会期间，艾可爱尔(IQAir)全球首席执行官弗兰克·哈姆(Frank Hammes)接受中新社记者专访时表示，中国绿色消费市场的蓬勃发展是全球绿色低碳产品迭代的巨大机遇。",
