    "content": "新华社北京11月7日电（记者孙奕、冯歆然）第七届世界媒体峰会国际主流媒体合作高端对话会7日在北京举行。新华社、美联社、路透社、法新社、美国有线电视新闻网（CNN）负责人就智能时代媒体演变的方向、路径和对策展开探讨，表示愿以本届峰会为契机深化交流互鉴。 新华社社长傅华表示，各方通过世界媒体峰会这一平台，围绕媒体变革与发展展开了富有现实意义的深入讨论，彰显媒体对促进人类社会发展进步怀有共同关切、肩负共同使命。人工智能技术发展日新月异，媒体从业者要善用技术赋能，同时维护主流媒体公信力。新华社愿与各方加强对话，推动行业发展…"
