    "content": "中新网沈阳11月7日电 11月7日，中国共产党沈阳市第十五届委员会第一次全体会议选举霍步刚为市委书记，马珊珊(女)、魏红江为市委副书记。中国共产党沈阳市第十五届纪律检查委员会第一次全体会议选举张吉慧为市纪律检查委员会书记。(完)"
