    "description": "中新网江西余干11月7日电(赖晗泽)作为江西省的传统农业大县，地处鄱阳湖畔的上饶市余干县耕地资源丰富。但由于过去相关部门在土地管理方面缺乏协作，导致当地早年整治完成的部分耕地正面临耕作层偏薄、有机质不足等问题，极易陷入“整治后退化、退化后复整”的风险。",
    "content": "中新网江西余干11月7日电(赖晗泽)作为江西省的传统农业大县，地处鄱阳湖畔的上饶市余干县耕地资源丰富。但由于过去相关部门在土地管理方面缺乏协作，导致当地早年整治完成的部分耕地正面临耕作层偏薄、有机质不足等问题，极易陷入“整治后退化、退化后复整”的风险。"
