    "title": "全球媒体人工智能应用标准共建计划正式启动",
    "link": "http://www.news.cn/20261107/baec9da2de994ec588b2a5cd64f8278d/c.html",
    "pub_date": "2026-11-07 19:17:29",
    "author": "",
    "description": "新华社北京11月7日电（记者周圆）7日，在第七届世界媒体峰会开幕式上，由新华通讯社发起的全球媒体人工智能应用标准共建计划正式启动。 该共建计划旨在邀请全球重要媒体及专业机构参与共建应用标准，共同维护信息真实、保障数据安全、恪守新闻伦理，维护全球新闻传播公信力。包括发起方新华通讯社在内，22家中外机构加入了共建计划，首批共建伙伴有人民日报社、中央广播电视总台、俄罗斯塔斯社、马来西亚国家新闻社、南非独立传媒集团等中外主流媒体和专业机构。 记…",
