    "content": "11月7日，第九届中国国际进口博览会主宾国加拿大专场对接会暨“出口中国”国别专场活动在国家会展中心（上海）如期启幕。本次活动由中国国际进口博览局、商务部外贸发展事务局、加拿大驻上海总领事馆与中国银行联合主办，中行上海市分行全程护航，以全链条专业撮合与金融服务赋能中加企业精准对接，为两国经贸合作注入强劲的金融动能。 作为本届进博会主宾国，加拿大携120家优质企业赴约而来，展品覆盖消费品、农业食品、保健品三大优势赛道。本次专场活动以精准撮合为核心，近100家加拿大展商企业与国内商超便利店、电商平台、新零售渠道商、代理经…"
