    "description": "11月7日下午，房新文总领事应约同维多利亚州州长卡罗尔紧急通话。卡罗尔对11月6日晚一名中国公民在墨尔本市区不幸遇害身亡深感痛心、深表震惊，表示凶手目前已被警方逮捕，请房总领事向遇害者家属转达他的深切哀悼和诚挚慰问。 房总领事允尽快向家属转告，并要求卡罗尔州长和维州政府及警方依法公正处理此案，严惩凶手，切实维护中国公民生命安全和合法权益。 卡罗尔表示，我们将坚定表明立场，绝不容忍这样的行径，正义必须得到伸张。",
    "content": "11月7日下午，房新文总领事应约同维多利亚州州长卡罗尔紧急通话。卡罗尔对11月6日晚一名中国公民在墨尔本市区不幸遇害身亡深感痛心、深表震惊，表示凶手目前已被警方逮捕，请房总领事向遇害者家属转达他的深切哀悼和诚挚慰问。 房总领事允尽快向家属转告，并要求卡罗尔州长和维州政府及警方依法公正处理此案，严惩凶手，切实维护中国公民生命安全和合法权益。 卡罗尔表示，我们将坚定表明立场，绝不容忍这样的行径，正义必须得到伸张。"
