    "content": "新华社广州11月7日电（记者徐弘毅、顾天成）世界卫生组织性传播感染预防与创新合作中心11月7日在广州揭牌成立，中心依托南方医科大学皮肤病医院（广东省皮肤性病防治中心）、南方医科大学全球健康研究院设立，旨在服务全球中低收入国家性病防控能力建设。 中心主任杨斌介绍，合作中心将围绕能力建设、检测创新与推广、监测体系建设三大核心职能开展系统性、前瞻性国际合作研究。 其中，在能力建设方面，合作中心将牵头研发标准化“终止性传播感染流行综合策略高级课程班”系列培训体系，计划至2030年，为全球15个中低收入国家培训100名性病防…"
