    "description": "新华社北京11月7日电 美国2026年中期选举结束，美国司法部3名高级别官员相继辞职。据美国媒体分析，司法部出现“离职潮”在意料之中。随着共和党失去国会参众两院控制权，特朗普政府将陷入“跛脚”困境，司法部一些官员重返回报丰厚的律所工作并不意外。 美司法部长托德·布兰奇6日宣布，佛罗里达州南区联邦检察官贾森·雷丁·基尼奥内斯、分管国家安全事务的助理司法部长约翰·艾森伯格辞职。一天前，布兰奇证实分管民权事务的助理司法部长哈米特·迪隆辞职。 …",
