    "content": "新华社北京11月7日电（记者樊曦）记者7日从中铁十八局集团有限公司获悉，国家重点水利工程浙江镜岭水库关键输水隧洞建设取得新突破，应用于这一工程的“镜岭2号”全断面隧道掘进机（TBM）顺利掘进突破万米大关，实现在“长距离、极硬岩、多断层”复杂地质条件下顺利推进隧洞施工。 浙江镜岭水库工程位于绍兴，是集防洪、供水、灌溉等主要功能于一体的国家重大水网工程，是浙江水网乃至东南地区水网的重要节点工程。工程分为水库枢纽工程和输水工程两大部分，输水线路长约76.3公里，其中“镜岭2号”全断面隧道掘进机（TBM）应用于全长超过13…"
