    "content": "中国驻墨尔本总领事馆通报，熊猫外卖一名华人骑手在墨尔本遇害，为此要求当局严惩凶手。 中国驻墨尔本总领事馆星期六（11月7日）在微信公众号上通报，一名中国公民当地时间星期五（11月6日）晚间在墨尔本市区遇害身亡，目前嫌犯已被当地警方缉拿归案。 中领馆对此高度重视，第一时间启动领事保护应急机制，要求警方全力彻查此案，依法、公正处理，严惩肇事凶手，切实维护中国公民合法权益。 中领馆已及时与遇害者家属取得联系，通报情况，正在会同有关方面为家属善后提供便利。 中领馆对同胞遇害深感悲痛，对其家属表示诚挚慰问，将继续同当地有关部…"
