    "content": "据《参考消息》报道，日本三丽鸥公司6日表示，鉴于该公司与热门电视剧《VIVANT》(《别班》)的联名商品受到中国方面批评并下架，公司将加强在开展联合开发项目时的审查机制。 共同社报道称，在6日举行的2026年9月中期业绩线上发布会上，三丽鸥常务执行董事松本成一郎回应提问时解释称，双方的联合开发合作是基于此前播出的《VIVANT》第一季内容决定的，而此次引发中方批评的是第二季情节：把中国人拍成惨无人道的施暴者，把日本自卫队情报人员美化成正义反击者。 松本成一郎表示，三丽鸥始终将“大家和睦相处”作为企业理念。虽然联名商…"
