    "description": "中新网昆明11月7日电 (黄兴鸿)云南省昆明市石林彝族自治县成立70周年庆祝大会7日在该县民族体育场举行。身着盛装的各族民众欢聚一堂，共同庆祝这一重要时刻。全国人大民委、国家民委派出祝贺团对石林彝族自治县成立70周年表达祝贺，中央民族歌舞团进行慰问演出。",
    "content": "中新网昆明11月7日电 (黄兴鸿)云南省昆明市石林彝族自治县成立70周年庆祝大会7日在该县民族体育场举行。身着盛装的各族民众欢聚一堂，共同庆祝这一重要时刻。全国人大民委、国家民委派出祝贺团对石林彝族自治县成立70周年表达祝贺，中央民族歌舞团进行慰问演出。"
