    "content": "在全球发展面临多重挑战、联合国2030年可持续发展议程进入关键阶段之际，中国与联合国开发计划署（UNDP）的合作迎来新进展。 11月6日，联合国开发计划署署长亚历山大·德克罗在首次正式访华期间接受澎湃新闻（www.thepaper.cn）等媒体采访时表示，中国与联合国开发计划署已经合作近50年，双方的合作关系正在变得更加具有战略意义，即将在上海设立的联合国开发计划署全球可持续发展中心将成为双方深化合作的重要平台。 11月4日，商务部部长王文涛与联合国开发计划署署长亚历山大·德克罗在上海签署协定，确认将在上海设立联合…"
