    "content": "新华社北京11月7日电 美国白宫6日公布总统特朗普计划修建的巨型“凯旋门”新设计方案，并将其定位为纪念美国军事历史的建筑。此前一天，美国一名联邦法官下令暂缓“凯旋门”项目施工。 根据白宫推介新网站公布的方案，这座凯旋门正式名称拟定为“美国军事凯旋门”，高约76米，计划建在林肯纪念堂与阿灵顿国家公墓之间。新版效果图显示，建筑主体采用灰色花岗岩，配有大量金色装饰，刻有“美国黄金时代”等金色字样。建筑顶部有三座镀金雕像，其中一座女子雕像手持火炬。 这是9月19日拍摄的美国国会大厦、华盛顿纪念碑、林肯纪念堂和海军陆战队纪念…"
