    "description": "当地时间11月4日，苹果研究团队披露了人形机器人自主控制系统HALO。调用千问模型在宇树G1上验证，在6个未预先扫描或建图的真实环境中开展360次单项任务测试，平均成功率为91%。",
    "content": "当地时间11月4日，苹果研究团队披露了人形机器人自主控制系统HALO。调用千问模型在宇树G1上验证，在6个未预先扫描或建图的真实环境中开展360次单项任务测试，平均成功率为91%。"
