    "content": "新华社北京11月7日电 第七届世界媒体峰会7日在北京开幕。中共中央政治局委员、中宣部部长李书磊出席开幕式并发表主旨演讲。中共中央政治局委员、北京市委书记尹力出席并致辞。 与会嘉宾认为，在习近平主席致第四届世界媒体峰会贺信精神指引下，五年来峰会影响力不断提升，各国媒体合作持续深化。当前全球人工智能技术创新进入前所未有的活跃期，为媒体发展带来了机遇和挑战。如何适应舆论生态深刻变革、促进全球媒体转型发展，如何发挥媒体独特优势、推动全球人工智能治理不断完善，需要各方深入思考、共同作答。 与会嘉宾表示，技术发展越迅猛，越是要…"
