    "description": "马来西亚国家新闻社（马新社）主席黄振威日前在接受新华社记者专访时表示，在北京召开的第七届世界媒体峰会为各国新闻工作者提供了学习知识、交流经验、增进了解的重要平台。他期待峰会能够推动各方开展务实合作，为全球南方国家媒体发展提供更多助力。 记者：黎淑同、袁睿、王嘉伟 报道员：祖尔、谭耀明 新华社音视频部制作",
