    "description": "联合国开发计划署计划进一步深化与中国在可持续发展领域的合作。联合国开发计划署署长亚历山大·德克罗11月4日至6日访问中国，在北京和上海开展系列高层会晤与交流，与各方围绕全球发展合作、南南合作及加快落实联合国2030年可持续发展议程等议题交换意见，共同探讨应对全球发展挑战、加强多边合作的路径。 联合国开发计划署署长亚历山大·德克罗于北京接受媒体群访。（联合国开发计划署供图） 亚历山大·德克罗表示，47年来，联合国开发计划署与中国始终携手同…",
    "content": "联合国开发计划署计划进一步深化与中国在可持续发展领域的合作。联合国开发计划署署长亚历山大·德克罗11月4日至6日访问中国，在北京和上海开展系列高层会晤与交流，与各方围绕全球发展合作、南南合作及加快落实联合国2030年可持续发展议程等议题交换意见，共同探讨应对全球发展挑战、加强多边合作的路径。 联合国开发计划署署长亚历山大·德克罗于北京接受媒体群访。（联合国开发计划署供图） 亚历山大·德克罗表示，47年来，联合国开发计划署与中国始终携手同行。近期，联合国开发计划署与中国政府签署关于在上海设立联合国开发计划署全球可持续…"
