    "description": "近日，网上掀起“手搓”纸壳机器人之风，网友纷纷展示自己制作的纸壳机器人。其中，一段超50万网友观看的纸壳机器人视频引发关注。记者日前与该创作者面对面，听他讲解机器人的制作原理。 纸盒虽小，却装得下巧思与热爱；话语不长，藏着对未来的期许与笃定。 作者：陈柱佐、朱浩宇 新华社音视频部制作",
    "content": "近日，网上掀起“手搓”纸壳机器人之风，网友纷纷展示自己制作的纸壳机器人。其中，一段超50万网友观看的纸壳机器人视频引发关注。记者日前与该创作者面对面，听他讲解机器人的制作原理。 纸盒虽小，却装得下巧思与热爱；话语不长，藏着对未来的期许与笃定。 &nbsp; 作者：陈柱佐、朱浩宇 新华社音视频部制作"
