    "description": "新华社石家庄11月7日电（记者苏凯洋）河北省保定市清苑区人民政府发布情况通报称，7日10时50分，清苑区消防救援大队接报，清苑区跨沧榆高速（沧州方向K105+550处）在建项目施工现场，钢桁架顶推作业过程中发生桥体脱落。经初步核实，事故造成3名施工人员、1名过往货车司机受伤，其中2名施工人员伤势较重。所有伤者已送医救治。 事故发生后，清苑区委、区政府立即组织卫健、应急、公安、消防等单位开展人员救治、交通疏导、隐患排查等工作。目前，当地正…",
    "content": "新华社石家庄11月7日电（记者苏凯洋）河北省保定市清苑区人民政府发布情况通报称，7日10时50分，清苑区消防救援大队接报，清苑区跨沧榆高速（沧州方向K105+550处）在建项目施工现场，钢桁架顶推作业过程中发生桥体脱落。经初步核实，事故造成3名施工人员、1名过往货车司机受伤，其中2名施工人员伤势较重。所有伤者已送医救治。 事故发生后，清苑区委、区政府立即组织卫健、应急、公安、消防等单位开展人员救治、交通疏导、隐患排查等工作。目前，当地正在加紧现场处置，确保沧榆高速尽快恢复通行。事故原因调查、善后等工作正在进一步开展…"
