    "description": "新华社北京11月7日电 全国人大常委会副委员长郑建邦7日在京出席非洲国家议员研讨班开班式并致辞。他表示，今年是中非开启外交关系70周年，中国全国人大愿同非洲各国议会和泛非议会一道，深化立法机构交流互鉴，推进中非“十大伙伴行动”，为中非务实合作提供法律和政策支持。",
