    "content": "新华社三亚11月7日电 题：鸣笛起锚 中国第43次南极考察队出征 新华社记者邹多为、戴锦镕、王立彬 长风相送，极境可期。 11月7日，自然资源部组织的中国第43次南极考察队从海南三亚南山港鸣笛出征，奔赴南极。 此次考察采用“雪龙”号、“雪龙2”号和“大洋号”三船保障模式，国内100多家单位的600余名队员参加，预计将于2027年4月完成任务后返航。其中，“雪龙”号已于11月3日从上海出发直接前往南极，目前抵达赤道附近。 11月7日恰逢立冬。从热带出发，奔赴南极，这场远征看点满满。 “每次南极之旅都是挑战与收获并存，…"
