    "description": "伦敦市民从英格兰银行总部大楼前经过。11月5日，英国央行时隔3年首次宣布加息，基准利率从3.75%上调25个基点至4%。英国央行在决议声明中指出，全球能源价格受中东冲突影响而持续上升，英国9月CPI增幅达到3.5%，预计2027年中期将升至5%左右，因此有必要收紧货币政策以抑制通胀。英国央行货币政策委员会本次投票共有8人支持加息25个基点，1人支持加息50个基点。摄影师：Andy Rain",
    "content": "伦敦市民从英格兰银行总部大楼前经过。11月5日，英国央行时隔3年首次宣布加息，基准利率从3.75%上调25个基点至4%。英国央行在决议声明中指出，全球能源价格受中东冲突影响而持续上升，英国9月CPI增幅达到3.5%，预计2027年中期将升至5%左右，因此有必要收紧货币政策以抑制通胀。英国央行货币政策委员会本次投票共有8人支持加息25个基点，1人支持加息50个基点。摄影师：Andy Rain"
