    "content": "亚太经济合作组织（APEC）领导人非正式会议即将在深圳举行，继鼓励私家车停驶后，深圳多区进一步将范围扩展至电动自行车。市民若在会议周自愿停驶，可获电动自行车保险折扣。 据《21世纪经济报道》，截至星期五（11月6日）晚间，深圳已有南山、福田、罗湖、龙华、龙岗五区开放了电动自行车自愿停驶申报，申报成功并在11月16日至20日期间自愿停驶的居民，可在活动结束后享受电动自行车保险七折优惠。 以龙岗区为例，“i龙岗”小程序已开通“电动自行车停驶申报”入口，市民进入申报页面，完成实名认证后选定所在街道、社区，填报电动自行车具…"
