    "description": "11月6日晚，第九届中国非物质文化遗产博览会主题活动“非遗之夜”展演在重庆举行，各地特色非遗项目轮番亮相。当晚，“新韵重庆”无人机灯光秀将川剧、蜀绣、火锅等非遗元素呈现在夜空中，与两江四岸夜景交相辉映，展现传统非遗与现代光影相融的魅力。 记者：杨仕彦 新华社音视频部制作",
    "content": "11月6日晚，第九届中国非物质文化遗产博览会主题活动“非遗之夜”展演在重庆举行，各地特色非遗项目轮番亮相。当晚，“新韵重庆”无人机灯光秀将川剧、蜀绣、火锅等非遗元素呈现在夜空中，与两江四岸夜景交相辉映，展现传统非遗与现代光影相融的魅力。 记者：杨仕彦 新华社音视频部制作"
