    "title": "专访丨“让人工智能为新闻行业发展增添动力”——访伊斯兰堡战略研究所理事会主席哈立德·马哈茂德",
    "link": "http://www.news.cn/20261107/34c26f61bd3d4cb89b95d7b00ab7963e/c.html",
    "pub_date": "2026-11-07 14:36:33",
