    "description": "新华社宁波11月7日电（记者杨博毅、郁思辉）“如何在坚持公平、纯洁的体育价值观的前提下，继续保持举重运动的吸引力和竞争力？”国际举重联合会秘书长何塞·基尼奥内斯日前在宁波举重世锦赛期间接受采访时，提出了这样一个问题。 作为一项拥有悠久历史的运动，举重近年来面临着怎样吸引年轻人、如何焕发新生的必答题。在基尼奥内斯看来，“如果不主动改革、不断创新，举重运动就可能在未来变得像‘恐龙’一样，逐渐落后于时代。” 基尼奥内斯表示，“干净与公平”是举…",
    "content": "新华社宁波11月7日电（记者杨博毅、郁思辉）“如何在坚持公平、纯洁的体育价值观的前提下，继续保持举重运动的吸引力和竞争力？”国际举重联合会秘书长何塞·基尼奥内斯日前在宁波举重世锦赛期间接受采访时，提出了这样一个问题。 作为一项拥有悠久历史的运动，举重近年来面临着怎样吸引年轻人、如何焕发新生的必答题。在基尼奥内斯看来，“如果不主动改革、不断创新，举重运动就可能在未来变得像‘恐龙’一样，逐渐落后于时代。” 基尼奥内斯表示，“干净与公平”是举重项目的生存底线。他提到2008北京奥运会的赛后复检，田径和举重都查出了兴奋剂案…"
