    "content": "新华社北京11月7日电 7日，中国男足公布新一期26人集训名单，37岁的老队长吴曦时隔近三年重回国家队。 新一期名单中，包括吴曦、张玉宁、王钰栋、刘浩帆、李昊、徐彬、胡荷韬、拜合拉木、杨希9名在亚运会帮助中国队夺得铜牌的球员。其中，吴曦上次代表成年国家队出场还是在2024年1月举行的卡塔尔男足亚洲杯。 此外，中国队主教练邵佳一还征召了伤愈复出的蒋圣龙；布尼亚明和黄晟豪两名20岁以下小将再次入选。韦世豪未进入集训名单。 在今年9月至10月的上一期集训中，由于部分主力球员参加名古屋亚运会，阵容不整的中国队在重庆国际足球…"
