    "content": "民众长期以来对一些政策存在怨言，这些政策被视为背弃了原本的福祉承诺，并伴随着社会不平等而进一步加剧——受冲击的不只有最贫困群体，还有日趋窘迫的中产阶级。 除了利摩日市政厅，特别是那些面向“超级富豪”的奢侈品店，也成为部分街头抗议者的攻击目标。因为在那里，一双鞋的价格可能等于他们一个月的薪水。 南方周末记者 陈相成 责任编辑：毛淑杰 当地时间2026年11月5日，法国雷恩，抗议者参加示威活动。此次游行是全国行动日的一部分。图/视觉中国。 过去半个多月，一股“抗议潮”席卷欧洲多国。 在法国，全国性的抗议活动已上演多轮。…"
