    "content": "\"肯尼亚的茶叶、布隆迪的咖啡、乌干达的乳木果油……正在上海举行的第九届中国国际进口博览会（简称进博会）上，非洲国家带着特色产品和合作期待而来，在中国市场寻找发展机遇。\" 肯尼亚的茶叶、布隆迪的咖啡、乌干达的乳木果油……正在上海举行的第九届中国国际进口博览会（简称进博会）上，非洲国家带着特色产品和合作期待而来，在中国市场寻找发展机遇。 策划：詹勇 执行策划：刘洪 统筹：汤丹鹭 陈子夏 记者：陈畅 宿鑫 报道员：爱丽克斯 文字：高姗姗 刘菲 新华网海外社交媒体传播中心制作 （新华网原创新闻作品）"
