    "content": "新华社北京11月7日电 美国阿克西奥斯新闻网站6日援引知情人士消息报道，美国副总统万斯过去两周参与了与伊朗的间接磋商，旨在达成新的停火并重启伊核问题谈判。万斯直接介入意味着美伊之间最新一轮间接谈判“提级”。 据报道，万斯两周前致信伊朗最高国家安全委员会秘书穆赫辛·雷扎伊，提议恢复直接谈判。近来，万斯几乎每天都同卡塔尔首相兼外交大臣穆罕默德、巴基斯坦陆军参谋长穆尼尔等调解方沟通。万斯和调解方讨论了美伊未来几天内举行工作级别技术会议的可能性，但尚未敲定。 美国总统特朗普的特使威特科夫和特朗普女婿库什纳也参与磋商。知情人…"
